        // baseUrl is field-injected and still null here, so build full URIs per call.
        this.restClient = RestClient.create();
    }

    /**
     * Verify user email through external service
     */
    public boolean verifyEmail(String email) {
        try {
            Map<String, Object> body = restClient.get()
                .uri(baseUrl + "/verify/email?email={email}", email)
                .retrieve()
                .body(MAP_TYPE);
            if (body != null) {
                Object valid = body.get("valid");
                return Boolean.TRUE.equals(valid);
            }
            return false;
        } catch (Exception e) {
            // Log and return false on failure
            return false;
        }
    }

    /**
     * Send notification to external notification service
     */
    public void sendNotification(String userId, String message) {
        try {
            Map<String, String> payload = Map.of(
